import{z as A,x as B,o as t,c as p,q as l,j as s,D as E,d as r,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"SR 11-7 模型风险管理","description":"","frontmatter":{"title":"SR 11-7 模型风险管理","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sr-11-7-model-risk.md","filePath":"quant/sr-11-7-model-risk.md","lastUpdated":1791413859000}'),d={name:"quant/sr-11-7-model-risk.md"};function u(h,a,m,C,c,f){const n=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="sr-11-7-模型风险管理" tabindex="-1">SR 11-7 模型风险管理 <a class="header-anchor" href="#sr-11-7-模型风险管理" aria-label="Permalink to &quot;SR 11-7 模型风险管理&quot;">​</a></h1><div class="epigraph"><p>模型风险主要来自两条：模型相对其设计目标与既定用途存在根本错误；或者模型被误用、被用到超出其局限与假定的地方。有效挑战——由客观、知情、有能力促成改变的人做批判分析——是贯穿始终的原则。</p><footer>—— Board of Governors of the Federal Reserve System, SR 11-7, Supervisory Guidance on Model Risk Management, April 4, 2011；OCC Bulletin 2011-12 并行文本</footer></div><p><a href="/quant/us-t1-settlement">上一课</a> 把结算时钟写成资金计划的约束；约束背后的模型由谁验证？2011 年 4 月 4 日，美联储以监管信 SR 11-7 发布《模型风险管理监管指引》，货币监理署同步发布 OCC Bulletin 2011-12。FDIC 于 2017 年以 FIL-22-2017 采纳同一套原则。它不是交易所撮合规则，而是对银行控股公司与受监督银行如何<strong>开发、验证、使用</strong>定量方法的监管预期。定义很宽：凡用统计、经济、金融或数学理论把输入变成定量估计的方法、系统或途径，都是模型；输入可以部分是定性或专家判断，只要输出是定量的。估值、风险计量、资本、限额、客户资产、监管报告与公开披露都在范围内。本篇把这份公开指引读成量化研究的约束：模型清单、独立验证与用途限制，而不是把验证写成可绕过的检查清单游戏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>危机之后，监管不再满足于「有人给定价模型签过字」。SR 11-7 要管的是决策依赖错误输出或误解输出时所导致的财务损失、错误决策与声誉损害。风险随复杂性、输入不确定、用途广度与潜在影响上升；还要管<strong>加总</strong>：许多模型共享假设、数据与方法，单体看起来可接受，组合在同一宏观情景下一起坏。量化团队日常用的波动、因子、定价、做市强度、<a href="/quant/var-methods">VaR</a> 与机器学习信号，只要输出进入额度、估值或客户决策，就可能落入这个定义，而不能用「这只是研究脚本」自动豁免。</p><p>指引把模型拆成三块：信息输入（数据与假设）、加工（把输入变成估计）、报告（把估计变成可用的业务信息）。错误可以出在任何一块：用了有前视的数据、公式推错、报告层把置信区间丢掉只留一个点估计。第二类风险——误用——往往更大：一个在正常市场校准的流动性模型被拿到压力日决定对冲规模；一个只对流动股票验证过的冲击模型被用到停牌重开。SR 11-7 要机构主动管理这两类，而不是等回测破裂。</p><p><span class="marginnote">直觉类比：「许多模型共享假设」像同一栋楼所有房间共用一根地线——每间屋子的电器单独检查都合格，但地线一断，整栋楼同时出事。这就是加总模型风险：单体验证通过不等于组合安全，还要检查它们是否踩在同一条会一起断的假设上（同一个数据源、同一段平静期校准）。</span></p><h3 id="「有效挑战」不是第二个人点头" tabindex="-1">「有效挑战」不是第二个人点头 <a class="header-anchor" href="#「有效挑战」不是第二个人点头" aria-label="Permalink to &quot;「有效挑战」不是第二个人点头&quot;">​</a></h3><p>有效挑战（effective challenge）被写成：客观、知情的当事人能够识别局限并促成相应改变。它依赖激励、能力与影响力的组合。验证团队若汇报给模型开发负责人、薪酬与模型上线绑定、或者看不懂假设，就没有挑战。能力意味着验证者要能复现、能提出替代假设、能读懂用途，而不是只会核对文档目录。影响力意味着验证意见可以挡住上线或强制限制用途。把验证定义成「开发写完说明书、验证改几个错别字」，不符合文本。</p><p><span class="marginnote">术语翻译：「有效挑战」用大白话说就是——由一个汇报线独立、看得懂模型、并且有权喊停的人，专门负责找茬，找到能逼你改模型或改用途为止。「第二个人看过并点头」不满足定义，因为那既不客观也无影响力。</span></p><p><span class="marginnote">重要性（materiality）决定投入强度，不决定是否在清单上。低重要性模型可以简化验证，但不能从未登记。反过来，高重要性模型的验证频率与深度应随用途变：同一定价引擎若从内部研究改成监管资本，重要性立刻上升，旧的验证不够。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>框架是三根柱子，必须同时在，而不是选做。</p><p>第一，开发、实施与使用。开发要有清晰的设计目标、理论依据、数据选择与处理、假设检验、以及已知局限。实施包括代码、系统与数据管道与文档一致，变更要有控制。使用必须落在验证过的范围内：输入分布、产品、市场状态若漂移，应触发再验证或用途限制。SR 11-7 明确：复杂到无法解释的加工，并不自动合格——可解释性与文档是使用的前提。</p><p>第二，验证。验证独立于开发，覆盖概念健全性（conceptual soundness）、持续监测与结果分析（outcomes analysis）。概念健全性检查理论、假设、数据与数学是否匹配既定用途；持续监测看上线后输入、输出与稳定性；结果分析把预测与事后实现对照，包括回测与基准。验证不是一次性证书：材料变更、用途扩展、表现退化都要再验证。厂商模型同样在范围内，不能因为外包就把有效挑战外包掉——机构仍对用途负责。</p><p>第三，治理、政策与控制。董事会与高管设定模型风险偏好，政策规定清单、分级、验证周期、例外与问责。模型清单（inventory）应覆盖在用、在开发、最近停用的模型，避免影子电子表格。内部审计检查框架是否真转起来，而不是自己当验证者。这与<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>是同一类边界：谁有权改模型、谁有权批准用途，不能是同一次网格搜索。</p> \\[\\mathrm{MR} = \\underbrace{\\Pr(\\text{模型错误})\\times\\text{损失}}_{\\text{规格失败}} + \\underbrace{\\Pr(\\text{超范围使用})\\times\\text{损失}}_{\\text{用途失败}}. \\]<p>SR 11-7 没有给出这个公式，但它的两分法就是这两项。管理意味着同时压概率与压一旦失败时的暴露：限额、叠加人工判断、保守调整、停止使用。</p><h3 id="结果分析对不上「样本内更好」" tabindex="-1">结果分析对不上「样本内更好」 <a class="header-anchor" href="#结果分析对不上「样本内更好」" aria-label="Permalink to &quot;结果分析对不上「样本内更好」&quot;">​</a></h3><p>量化研究习惯用样本内损失下降证明模型进步。监管文本要的是：在既定用途上，相对简单基准与相对实现值，模型是否仍有技能，以及失败模式是否可接受。对风险模型，<a href="/quant/var-backtest">VaR 回测</a>是结果分析的一种，不是全部——还要看压力、看分位数以外的路径、看组合改变之后校准是否仍成立。对定价模型，要对可观察的市场价格，也要对对冲残差。对机器学习信号，要声明训练窗口、特征是否点-in-time、尝试次数，否则验证看到的是<a href="/quant/overfit-as-risk">过拟合</a>后的成绩单。SR 11-7 允许与风险相称的验证技术，不规定必须用某一种检验；它规定的是：要有客观的、事先写明的接受标准，不能上线后再选一个会通过的指标。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>清单与分级把模型变成可治理对象。没有清单，有效挑战无处落脚。分级通常按影响、复杂度与用途：资本与估值最高，研究原型最低，但最低仍要登记。变更管理把「改一行代码」分成材料 / 非材料：材料变更阻断使用直到再验证。用途限制是比「通过 / 不通过」更常见的中间态：模型可以在流动品种、在正常波动使用，压力情景改用后备方法。这与量化里的制度掩码同类——公开规则把某些动作直接禁掉，模型治理把某些输入—输出对禁掉。</p>',22)),(t(),s(o,null,{default:E(()=>[i(n,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20LR%0A%20%20New%5B%22%E6%96%B0%E6%A8%A1%E5%9E%8B%E5%BC%80%E5%8F%91%E5%AE%8C%E6%88%90%22%5D%20--%3E%20Reg%5B%22%E7%99%BB%E8%AE%B0%E5%85%A5%E6%B8%85%E5%8D%95%E5%B9%B6%E5%88%86%E7%BA%A7%22%5D%0A%20%20Reg%20--%3E%20Val1%5B%22%E9%A6%96%E6%AC%A1%E7%8B%AC%E7%AB%8B%E9%AA%8C%E8%AF%81%22%5D%0A%20%20Val1%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20Live%5B%22%E9%99%90%E5%AE%9A%E7%94%A8%E9%80%94%E4%B8%8A%E7%BA%BF%22%5D%0A%20%20Live%20--%3E%20Mon%5B%22%E6%8C%81%E7%BB%AD%E7%9B%91%E6%B5%8B%E4%B8%8E%E7%BB%93%E6%9E%9C%E5%88%86%E6%9E%90%22%5D%0A%20%20Chg%5B%22%E6%9D%90%E6%96%99%E5%8F%98%E6%9B%B4%20%2F%20%E7%94%A8%E9%80%94%E6%89%A9%E5%B1%95%22%5D%20--%3E%20Reval%5B%22%E8%A7%A6%E5%8F%91%E5%86%8D%E9%AA%8C%E8%AF%81%22%5D%0A%20%20Mon%20--%3E%7C%22%E6%BC%82%E7%A7%BB%E6%88%96%E9%80%80%E5%8C%96%22%7C%20Reval%0A%20%20Reval%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20Live%0A%20%20Reval%20--%3E%7C%22%E4%B8%8D%E9%80%9A%E8%BF%87%22%7C%20Out%5B%22%E9%99%90%E7%94%A8%E9%80%94%20%2F%20%E5%90%8E%E5%A4%87%E6%96%B9%E6%B3%95%20%2F%20%E5%81%9C%E7%94%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<p><span class="marginnote">常见误区：初学者把验证当成「一年一次的年检」，通过后就把证书放进抽屉。SR 11-7 的框架里，验证状态是随使用而失效的：换数据源、换市场、用途从研究变成监管资本，任何一项都立刻让旧的「通过」作废，必须重新走流程。</span></p><p>厂商与开源组件不降低标准。SR 11-7 要求理解厂商模型的逻辑、假设与局限，有权获得足够信息做有效挑战，并用自有组合做结果分析。把供应商的验证报告复印进文件夹，不算完成。对外部数据同样：输入组件是模型的一部分，数据中断、定义修订、生存者偏差都是模型风险。</p><p><span class="marginnote">「我们用的是监管标准模型」不是豁免。指引覆盖用来满足监管报告的方法本身。内部评级、损失给定违约、压力测试若被用于资本，验证标准往往更高，因为用途已经是审慎决策。</span></p><h3 id="人工智能没有单独豁免条款" tabindex="-1">人工智能没有单独豁免条款 <a class="header-anchor" href="#人工智能没有单独豁免条款" aria-label="Permalink to &quot;人工智能没有单独豁免条款&quot;">​</a></h3><p>2011 年文本没有写深度学习，定义却已经按输出是否定量来划界。信用评分、反洗钱监测、估值代理、生成式工具若输出进入额度或客户决策，仍可能是模型。挑战的难点从「推导公式」变成「数据与用途」：训练分布、漂移、提示与工具是否改变加工组件。SR 11-7 的原则仍然适用：要有开发文档、独立验证、清单与用途限制；不能因为权重不可读就跳过概念健全性——那时应限制用途、加强监测与人工覆盖，而不是声称无法验证因此不验证。与<a href="/quant/eu-ai-act-finance">欧盟 AI 法案</a>的交叉是：后者按用途风险分级并赋予法律义务，前者是美国银行监管的模型治理预期；两套可以映射，不能互相替代。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SR 11-7 是监管指引，不是制定法上的规则，但检查中按此原则提问，事项整改与执法常引用它。适用范围是美联储与 OCC（及后来 FDIC）监督的银行组织，按规模与复杂度相称实施；非银行量化基金没有被这条信直接点名，却大量借用其词汇。相称性不是「小机构可以没有验证」，而是验证深度与模型风险状况匹配。</p><p>本篇不讨论如何把模型藏出清单或把验证做成形式签字。公开文本的方向相反：影子模型、开发者自验证、用途蔓延，正是要被治理掉的行为。对研究工作流，可执行的约束是：凡进入模拟或实盘决策的估计器，预先登记、冻结版本、写明用途与局限、留出独立的人做挑战，并把尝试次数写进验证包。这与隔离研究 / 模拟 / 实盘一致。</p><p><span class="marginnote">验证通过不表示模型为真。指引反复强调每个模型都有局限。通过的含义是：在声明的用途与监测计划下，残余模型风险被接受。用途一变，通过状态失效。</span></p>',9)),(t(),s(o,null,{default:E(()=>[i(n,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20Def%5B%22%E6%A8%A1%E5%9E%8B%3A%20%E8%BE%93%E5%85%A5%20%E2%86%92%20%E5%8A%A0%E5%B7%A5%20%E2%86%92%20%E6%8A%A5%E5%91%8A%22%5D%20--%3E%20Inv%5B%22%E5%85%A8%E6%9C%BA%E6%9E%84%E6%A8%A1%E5%9E%8B%E6%B8%85%E5%8D%95%22%5D%0A%20%20Inv%20--%3E%20Dev%5B%22%E5%BC%80%E5%8F%91%20%2F%20%E5%AE%9E%E6%96%BD%20%2F%20%E4%BD%BF%E7%94%A8%22%5D%0A%20%20Inv%20--%3E%20Val%5B%22%E7%8B%AC%E7%AB%8B%E9%AA%8C%E8%AF%81%22%5D%0A%20%20Inv%20--%3E%20Gov%5B%22%E6%B2%BB%E7%90%86%E4%B8%8E%E8%91%A3%E4%BA%8B%E4%BC%9A%E7%9B%91%E7%9D%A3%22%5D%0A%20%20Val%20--%3E%20CS%5B%22%E6%A6%82%E5%BF%B5%E5%81%A5%E5%85%A8%E6%80%A7%22%5D%0A%20%20Val%20--%3E%20Mon%5B%22%E6%8C%81%E7%BB%AD%E7%9B%91%E6%B5%8B%22%5D%0A%20%20Val%20--%3E%20OA%5B%22%E7%BB%93%E6%9E%9C%E5%88%86%E6%9E%90%22%5D%0A%20%20CS%20--%3E%20Use%5B%22%E5%85%81%E8%AE%B8%E7%9A%84%E7%94%A8%E9%80%94%E8%8C%83%E5%9B%B4%22%5D%0A%20%20Mon%20--%3E%20Use%0A%20%20OA%20--%3E%20Use%0A%20%20Use%20--%3E%20Limit%5B%22%E8%B6%85%E8%8C%83%E5%9B%B4%E5%88%99%E9%99%90%E5%88%B6%E6%88%96%E5%81%9C%E7%94%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"SR 11-7 / OCC 2011-12 把模型定义为把输入变成定量估计的方法，并要求管理错误与误用两类风险。"),e("li",null,"三根柱子是开发实施与使用、独立验证、治理清单与控制；贯穿原则是有效挑战。"),e("li",null,"验证覆盖概念健全性、持续监测与结果分析，且随用途变更而持续，不是一次性证书。"),e("li",null,"厂商模型与监管用途模型不豁免；加总风险来自共享假设。"),e("li",null,"机器学习与生成式系统只要输出进入决策，就按同一套原则登记与限制用途。"),e("li",null,"相称性调节强度，不删除清单义务。"),e("li",null,"出处：Federal Reserve SR 11-7（2011-04-04）及附件 Supervisory Guidance on Model Risk Management；OCC Bulletin 2011-12；FDIC FIL-22-2017。")],-1))])}const S=A(d,[["render",u]]);export{R as __pageData,S as default};
